require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='dashboard';$pageTitle='Finance Officer Dashboard';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);if($uid<=0){http_response_code(403);exit('Invalid Finance Officer account.');}$stats=['attendance'=>0,'draft'=>0,'pending'=>0,'approved'=>0,'exceptions'=>0];if(fo_has_table($conn,'finance_attendance_approved')){$r=$conn->query("SELECT COUNT(*) total FROM finance_attendance_approved WHERE approval_status='approved'");$stats['attendance']=(int)($r?$r->fetch_assoc()['total']??0:0);}if(fo_has_table($conn,'stipend_schedules')){$s=$conn->prepare("SELECT SUM(status='draft') draft,SUM(status='awaiting_approval') pending,SUM(status='approved') approved FROM stipend_schedules WHERE created_by=?");$s->bind_param('i',$uid);$s->execute();$stats=array_merge($stats,$s->get_result()->fetch_assoc()?:[]);$s->close();}$recent=[];if(fo_has_table($conn,'stipend_schedules')){$s=$conn->prepare("SELECT id,schedule_reference,period_start,period_end,status,participant_count,total_amount FROM stipend_schedules WHERE created_by=? ORDER BY created_at DESC LIMIT 5");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$recent[]=$x;$s->close();}$cfg=fo_config($conn);$first=trim((string)($user['first_name']??'Finance Officer'));require __DIR__.'/_layout_start.php';?>
<section class="fo-hero"><div><span class="fo-eyebrow"><i class="fas fa-money-check-dollar"></i> Stipend Operations</span><h2>Accurate schedules from approved attendance, <?= e($first) ?>.</h2><p>Prepare stipend schedules using approved attendance, expose every calculation basis and exception, preserve maker/checker segregation, and retain immutable approved history.</p><div class="fo-hero__actions"><a class="fo-btn fo-btn--light" href="<?= url('finance_officer/attendance.php') ?>"><i class="fas fa-calendar-check"></i> Approved Attendance</a><a class="fo-btn fo-btn--glass" href="<?= url('finance_officer/schedules.php') ?>"><i class="fas fa-file-invoice-dollar"></i> Schedules</a></div></div><div class="fo-orb"><i class="fas fa-user-shield"></i><strong><?= (int)$cfg['maker_checker_enabled']===1?'ON':'OFF' ?></strong><span>maker/checker segregation</span></div></section>
<section class="fo-stats"><article><i class="fas fa-calendar-check"></i><strong><?= number_format((int)$stats['attendance']) ?></strong><span>Approved Attendance</span></article><article><i class="fas fa-file-pen"></i><strong><?= number_format((int)$stats['draft']) ?></strong><span>Draft Schedules</span></article><article><i class="fas fa-user-check"></i><strong><?= number_format((int)$stats['pending']) ?></strong><span>Awaiting Approval</span></article><article><i class="fas fa-circle-check"></i><strong><?= number_format((int)$stats['approved']) ?></strong><span>Approved Schedules</span></article></section>
<div class="fo-grid"><section class="fo-card"><div class="fo-card__header"><h3>Recent Schedules</h3></div><?php if(!$recent):?><div class="fo-empty"><i class="fas fa-file-invoice-dollar"></i><strong>No schedules yet</strong><span>Prepare one from approved attendance.</span></div><?php else:?><div class="fo-list"><?php foreach($recent as $r):?><a href="<?= url('finance_officer/schedule_view.php?id='.(int)$r['id']) ?>"><div><strong><?= e($r['schedule_reference']) ?></strong><span><?= e(fo_date($r['period_start'])) ?> - <?= e(fo_date($r['period_end'])) ?> · <?= e(fo_money($r['total_amount'])) ?></span></div><span class="fo-status fo-status--<?= e(fo_status_class($r['status'])) ?>"><?= e(fo_label($r['status'])) ?></span></a><?php endforeach;?></div><?php endif;?></section><section class="fo-card"><div class="fo-card__header"><h3>Control Framework</h3></div><div class="fo-principles"><div><i class="fas fa-calculator"></i><strong>Visible calculation basis</strong><span>Attendance, rate, eligible days and exceptions stay visible.</span></div><div><i class="fas fa-user-shield"></i><strong>Maker cannot self-approve</strong><span>Segregation blocks final approval by the maker.</span></div><div><i class="fas fa-lock"></i><strong>Approved history is immutable</strong><span>Corrections create revisions instead of silent edits.</span></div></div></section></div>
